import{_ as t,c as a,o,ag as r}from"./chunks/framework.DZ_cNctr.js";const i="/docs/screenshots/scn-slide.webp",g=JSON.parse('{"title":"Leica SCN Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Leica SCN slides in your browser: every scanned region, brightfield and fluorescence. Free, nothing to install or convert.","frontmatter":{"title":"Leica SCN Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Leica SCN slides in your browser: every scanned region, brightfield and fluorescence. Free, nothing to install or convert."},"headers":[],"relativePath":"guides/leica-scn.md","filePath":"guides/leica-scn.md"}'),s={name:"guides/leica-scn.md"};function n(l,e,d,h,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="leica-scn-slides-in-the-browser" tabindex="-1">Leica SCN Slides in the Browser <a class="header-anchor" href="#leica-scn-slides-in-the-browser" aria-label="Permalink to &quot;Leica SCN Slides in the Browser&quot;">​</a></h1><p>Open the slides your Leica SCN400 saves, as they are. Nothing to convert, nothing to upload. A large slide starts showing right away, because the viewer reads only the part you look at.</p><p><img src="'+i+'" alt="Leica-2.scn open in the viewer, with its region list and macro picture"></p><h2 id="how-it-opens" tabindex="-1">How It Opens <a class="header-anchor" href="#how-it-opens" aria-label="Permalink to &quot;How It Opens&quot;">​</a></h2><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on the viewer, or click <strong>Open Image</strong> and <strong>Choose File</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A folder of slides</strong>, in Chrome and Edge. One slide opens, several show a list. See <a href="./local-files.html#open-a-folder">Local Files</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>Regions.</strong> A slide can hold several scanned regions. Pick one from the list, such as <strong>Region 1 (40x)</strong>.</li><li><strong>Macro.</strong> It appears under the title. Click it to enlarge it, and turn it if needed. A label may show patient details. The viewer shows it and never saves or sends it.</li><li><strong>Fluorescence.</strong> Each channel opens with its own colour and contrast.</li><li><strong>Colour profile.</strong> A slide that carries its scanner&#39;s colour profile is drawn with it. ICC in the RGB settings turns it off. See <a href="./channels.html#icc-colour-profile">Channels</a>.</li><li><strong>Z-stacks.</strong> The first plane opens, with a note.</li><li><strong>Pixel size and magnification.</strong> Both come from each region, so measurements read in µm and the zoom bar shows the objective. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><h2 id="if-a-slide-does-not-open" tabindex="-1">If a Slide Does Not Open <a class="header-anchor" href="#if-a-slide-does-not-open" aria-label="Permalink to &quot;If a Slide Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>JPEG 2000 or another compression</td><td>This SCN file uses a compression the viewer cannot read yet.</td></tr></tbody></table><h2 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h2><p>Import GeoJSON or OME-XML, and export both, from the <strong>Annotations</strong> panel. Send a link that opens the slide with its annotations. <a href="./annotation-exchange.html">Exchanging Annotations</a> shows how. To draw, measure and label shapes on the slide, see <a href="./annotations.html">Annotations</a>.</p><h2 id="public-slides-to-try" tabindex="-1">Public Slides to Try <a class="header-anchor" href="#public-slides-to-try" aria-label="Permalink to &quot;Public Slides to Try&quot;">​</a></h2><p><a href="https://openslide.org" target="_blank" rel="noreferrer">OpenSlide</a> shares test slides in its <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/Leica/" target="_blank" rel="noreferrer">Leica folder</a>. Download a slide, then drop it on the viewer. They are marked distributable.</p><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a slide by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><p>When a server cannot send parts of a file, the viewer says so. Download the slide and open it from your computer.</p><p>Addresses that start with <code>s3://</code> and <code>gs://</code> work too.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>Leica-2.scn</code> from the OpenSlide test data, free to use and distribute. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The slide is read in your browser. Opening one counts as one opened image of the kind &quot;Leica SCN file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p><p><small>Product names are trademarks of their owners. Find Nuclei is not affiliated with them.</small></p>',23)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
